#!/usr/bin/env python3
"""Read compiler evidence into a small human-readable plan; no planning."""
import json,argparse,hashlib
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--plan',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();v=json.loads(a.plan.read_text());g=v['program_graph'];l=g['ledger'];names={x['storage']:x['id'] for x in g['logical_data']};binding={b['allocation']:b for b in g['allocation_bindings']};activities={c['id']:c for c in v['direct_air_cost']['event_timing']['timing']['activities']};s=[]
s+=['# Concrete retained1024 execution plan','',f'Exact input: `{a.plan.resolve()}`; SHA256 `{hashlib.sha256(a.plan.read_bytes()).hexdigest()}`.',f'Graph `{v["program_graph_id"]}`; full priced native plan `{v["plan_id"]}`.','', 'This is the actual original-search winner, not a separately authored backend plan.','Source: X=A+1, B=X+2, C=X+X, 64×128 FP32. Eight blocks use one configuration.','', '## Allocations','', '| ID | Logical storage | Concrete memory | Owner | Size B | Addressing | Phase witness |','|---|---|---|---|---:|---|---|']
for i,x in enumerate(l['allocations']):
 b=binding[i];s.append(f'| {i} | {names[x["storage"]]} | {x["memory"]} | {b.get("spatial_owner","host/system")} | {x["bytes"]} | {b.get("addressing","legacy target default")} | [{x["begin_phase"]},{x["end_phase_exclusive"]}) |')
s+=['','All copies are row_major. Allocation alignment follows the referenced memory contract (default 1 byte in this architecture); this is not a complete statement of linker-selected hardware alignment. Four 4096-byte local slots reserve 16384 payload bytes under the unchanged 24576-byte policy. The real AIE separately declares a 4096-byte stack. System capacity is a boundary assumption rather than a measured DRAM capacity.','', '## First block copy/version identities','', '| Copy | Storage region / offsets / sizes | Version | Allocation | Creator | Users | Validity ordinal witness |','|---|---|---|---:|---|---|---|']
first=l['events'][:6];ids=sorted({c for e in first for c in e['reads']+e['writes']})
for i in ids:
 c=l['copies'][i];version=l['versions'][c['version']];reg=l['logical_regions'][version['region']];region=f'{names[reg["storage"]]} / {reg["offsets"]} / {reg["sizes"]}'
 s.append(f'| {i} | {region} | {c["version"]} | {c["allocation"]} | {c["created_by"]} | {c["users"]} | [{c["available_from"]},{c["released_after"]}) |')
s+=['','Copy 9 is the shared X region/version in allocation 6. Both computations read that exact copy; there is no X host allocation or transfer. These ordinals are topological validity witnesses, not device timestamp boundaries or inferred release activities.','', '## First block activities and assumed calendar','', '| Event | Kind / source task | Read copies → write copies | Dependencies | Resource / path | Assumed start–end us |','|---|---|---|---|---|---|']
for i,e in enumerate(first):
 t=activities[f'event.{i}'];s.append(f'| {i} | {e["kind"]} / task {e["task"]} | {e["reads"]} → {e["writes"]} | {e["depends_on"]} | {e["resource"]} / {e["link"] or "local"} | {1000*t["start_ms"]:.3f}–{1000*t["end_ms"]:.3f} |')
s+=['','Submit is assumed 0–100 us and setup 100–140 us. The following blocks repeat the same slot pattern on different logical regions; the last completion envelope gives 551.712 us. These times come directly from C++ ProgramTiming under declared assumptions. They are not hardware timestamps.','', '```mermaid','flowchart LR','  I0["Ain[k]"] --> P0["P[k]: X=A+1"]','  P0 --> B0["B[k]: X+2"]','  B0 --> C0["C[k]: X+X"]','  C0 --> O0["Bout[k]"]','  C0 --> Q0["Cout[k]"]','  C0 --> I1["Ain[k+1]: refill input slot"]','  I1 --> P1["P[k+1]: reuse local slots"]','  O0 --> P1','  Q0 --> P1','```','', 'Solid edges here include chosen single-core implementation ordering and lock release. Source semantics only require P→B and P→C. Both consumers read one X copy; overwriting its slot waits for both. The public DAG permits input refill while old outputs drain; the assumed shared DMA reservation can conservatively serialize that interval.','', 'Actual implementation: one A input flow, two B/C output flows, three merged whole-array runtime BDs, 24 inferred cyclic core transactions, no X BO/BD/flow. Static two-way causality is checked from actual lock/compute/BD/runtime control; it is not a claim that bandwidth arbitration or overlap was measured.','', 'Actual numerical outputs and all six paired comparisons are reported in the final independent observation report. The estimated winner is not a validated fine-grained performance winner.']
a.output.write_text('\n'.join(s)+'\n')
